function renderOffset(){const inputs=['growthCustom','feeCustom','captureCustom','allocationCustom','nearCustom','issuanceCustom','burnCustom'].map(id=>$(id).value.trim()===''?NaN:Number($(id).value)),[g,f,c,a,p,i,b]=inputs;if(inputs.some(v=>!finite(v))){$('requiredVolume').textContent='Check assumptions';$('crossingDate').textContent='—';$('offsetResult').textContent='—';$('offsetChart').replaceChildren();return}try{const h=+state.offsetHorizon,target=+state.offsetTarget/100,o={volume:B.volume,fee:f/100,capture:c/100,allocation:a/100,price:p,issuance:i*30.4375,dailyIssuance:i,burn:b,reduction:Number($('reductionCustom').value)/100,delay:Number($('delayCustom').value),duration:Number($('durationCustom').value),growth:g/100,horizon:h,target,lower:state.offsetIssuance==='lower',month:B.month},result=M.offset(o);$('requiredVolume').textContent=result.required===null?'Not achievable':money(result.required);$('requiredHint').textContent=versusCurrent(result.required,B.volume);$('crossingDate').textContent=result.cross?label(result.cross):'Not reached';$('crossingHint').textContent=result.cross?'Target '+state.offsetTarget+'%':'Within '+h+' months';$('offsetResult').textContent=percent(result.endOffset);const actual=D.months.find(r=>r.month===B.month),currentOffset=actual&&actual.mint>0&&(finite(actual.buy)&&finite(actual.burn))?(actual.buy+actual.burn)/actual.mint:null;$('offsetHint').textContent=versusCurrent(result.endOffset,currentOffset);syncInflation();$('growthValue').textContent=(customGrowth?'Custom: ':'')+g.toFixed(1)+'% per month';const series=[{name:'Issuance offset',color:'#218463',values:result.rows.map(r=>r.offset)}];if(compare){const other=M.offset({...compare,horizon:h,target,month:B.month});series.push({name:'Comparison',color:'#c48646',values:other.rows.map(r=>r.offset)});$('comparisonResults').innerHTML='<div><b>Your scenario</b><span>'+money(result.required)+' monthly volume needed</span><span>'+(result.cross?label(result.cross):'Not reached')+'</span><span>'+percent(result.endOffset)+' offset at month '+h+'</span></div><div><b>Comparison</b><span>'+money(other.required)+' monthly volume needed</span><span>'+(other.cross?label(other.cross):'Not reached')+'</span><span>'+percent(other.endOffset)+' offset at month '+h+'</span></div>'}draw('offsetChart',result.rows.map(r=>label(r.date)),series);$('offsetLegend').innerHTML=compare?'<span><i></i>Your scenario</span><span><i class="compare-dot"></i>Comparison</span>':'';$('offsetLegend').hidden=!compare;$('comparisonResults').hidden=!compare;$('removeComparison').hidden=!compare;$('compareScenario').textContent=compare?'Edit comparison':'Compare scenarios +';$('offsetMethod').innerHTML=`<p>Baseline volume: ${label(B.month)} (${money(B.volume)}). Recent trend compares the first and last 30 days of the saved 90-day activity window, expressed as a monthly rate. Slower/faster moves that rate by five percentage points. Fee and capture defaults are ratios of summed amounts across ${label(B.recentFrom)}–${label(B.month)}. Price uses the ${B.priceDate} saved observation.</p><p>Revenue = volume × fee rate × capture rate. Modelled NEAR purchases = revenue × allocation ÷ NEAR price. Issuance offset = (monthly burns + modelled purchases) ÷ monthly issuance. A crossing requires three consecutive projected months within the selected horizon. Monthly volume needed uses the issuance assumption at the end of that horizon. Zero fee, capture or allocation can make a target unattainable.</p><p>Latest issuance uses the average daily issuance across ${label(B.recentFrom)}–${label(B.month)} (${Math.round(B.dailyIssuance).toLocaleString()} NEAR/day), adjusted for the days in each projected month. The daily rate can be edited. Lower issuance applies a ${Number($('reductionCustom').value)}% reduction over ${Number($('durationCustom').value)} months after a ${Number($('delayCustom').value)}-month delay. The default schedule follows <a href="https://gov.near.org/t/hsp-029-establish-a-24-month-issuance-ramp-to-a-1-6-target-rate-of-near-token-emissions/42644" target="_blank" rel="noopener">HSP-029</a>. This is a scenario, not confirmation that the proposal schedule has started. Customise sets the final annualised issuance rate. The slider’s current upper value is derived from the observed daily issuance × 365 ÷ saved total supply; it is an estimate, not a separately verified protocol parameter. Use proposed reduction rate selects a 36% reduction from this baseline. The three-month delay and 24-month ramp remain in effect. Volume change versus current compares required volume with the latest complete month’s volume. Offset change versus current compares the final projected offset with actual burns plus recorded buybacks divided by issuance for that same month. Both changes are relative percentages, not percentage-point changes. Scenario comparisons change only the assumptions you edit; the two paths are not probabilities or a prediction range. Burns and price stay at the selected values. Allocation defaults to an assumed 100%; it is not a verified spending fraction. Buying tokens does not burn them or reduce total supply.</p><p>Saved data through ${B.through}. <a href="./data/performance.json" download>Protocol records</a> · <a href="./data/supply-history.json" download>Supply evidence</a> · <a href="https://docs.near-intents.org/resources/fees" target="_blank" rel="noopener">Fee documentation</a>.</p>`}catch(e){$('requiredVolume').textContent='Check assumptions';$('crossingDate').textContent='—';$('offsetResult').textContent='—';$('offsetChart').replaceChildren();$('crossingHint').textContent=e.message;}}
